\begin{definition}[The choice lift]\label{cl:lift}
Let $G$ be an SSG with $C=\Vmax\cup\Vmin$. The \emph{lifted system} $L(G)$ is
the set of pairs $(x,y)\in\mathbb R^{V}\times[0,1]^{C}$ with
\[
 \begin{aligned}
  &x(t_0)=0,\quad x(t_1)=1,\quad 0\le x\le 1,\\
  &x(v)=\tfrac12\bigl(x(v^{(0)})+x(v^{(1)})\bigr) &&(v\in\Vavg),\\
  &x(v)\ge x(v^{(i)})\ \ (i=0,1) &&(v\in\Vmax),\\
  &x(v)\le x(v^{(i)})\ \ (i=0,1) &&(v\in\Vmin),\\
  &x(v)=y_v\,x(v^{(0)})+(1-y_v)\,x(v^{(1)}) &&(v\in C).
 \end{aligned}
\]
The last family is bilinear; all the others are the rows of $Q(G)$
(\Cref{def:transport}). Write $L_{\mathrm{int}}(G):=L(G)\cap\{y\in\{0,1\}^{C}\}$.
\end{definition}

\begin{proposition}[The lift is exact, and already convex]\label{cl:exact-lift}
Let $G$ be stopping. Then (a) $(x,y)\in L(G)$ implies $x=w^{\ast}$, with no
integrality hypothesis; (b) $L(G)=\{w^{\ast}\}\times\operatorname{conv}(\Opt)$,
where $\Opt$ is the optimal subcube of \Cref{thm:opt-subcube}; (c) hence
$L(G)=\operatorname{conv}(L_{\mathrm{int}}(G))$: the lifted feasible set is its
own convex hull, cut out by the $N$ equalities $x=w^{\ast}$ together with at
most $|C|$ facets of the cube, and it has no disjunctive structure of
$2^{|\Vmin|}$ pieces at all.
\end{proposition}

\begin{definition}[The level-$j$ relaxation]\label{cl:rlt}
A \emph{level-$j$ point} is a family $(z^{S,T}\in\mathbb R,\;X^{S,T}\in\mathbb
R^{V})$ over disjoint $S,T\subseteq C$ with $|S|+|T|\le j$ such that
(i) $z^{\emptyset,\emptyset}=1$;
(ii) $z^{S,T}=z^{S\cup v,T}+z^{S,T\cup v}$ and $X^{S,T}=X^{S\cup v,T}+X^{S,T\cup v}$
for $|S|+|T|<j$, $v\notin S\cup T$;
(iii) $X^{S,T}(t_0)=0$, $X^{S,T}(t_1)=z^{S,T}$, $0\le X^{S,T}\le z^{S,T}\mathbf1$,
the average equalities and the Max/Min order rows, all homogenised;
(iv) $X^{S,T}(v)=X^{S,T}(v^{(0)})$ for $v\in S$ and $X^{S,T}(v)=X^{S,T}(v^{(1)})$
for $v\in T$. Put $R_j(G):=\{X^{\emptyset,\emptyset}\}$; it is the projection of
a linear programme of size $N^{O(j)}$ with coefficients in $\{0,\pm\frac12,\pm1\}$.
\end{definition}

\begin{lemma}[Level one is an intersection of hulls of faces]\label{cl:faces}
With $F_v^{i}:=\{x\in Q(G):x(v)=x(v^{(i)})\}$, a face of $Q(G)$,
$R_1(G)=\bigcap_{v\in C}\operatorname{conv}(F_v^{0}\cup F_v^{1})$.
\end{lemma}

\begin{theorem}[Rigid games are one linear programme]\label{cl:rigid}
Call $v\in C$ rigid if $x\mapsto x(v^{(0)})-x(v^{(1)})$ has constant weak sign
on $Q(G)$, and let $\mathrm{Rev}(G)$ be the set of the others (decidable by
$2|C|$ linear programmes). If every controlled vertex is rigid then
$R_1(G)=\{w^{\ast}\}$.
\end{theorem}

\begin{theorem}[The collapse level]\label{cl:collapse}
With $\rho_{\min}:=|\mathrm{Rev}(G)\cap\Vmin|$ and
$\rho_{\max}:=|\mathrm{Rev}(G)\cap\Vmax|$: $j\ge\min(k,\rho_{\min}+1)$ implies
$\min_{R_j}x=w^{\ast}$ pointwise, and $j\ge\min(m,\rho_{\max}+1)$ implies
$\max_{R_j}x=w^{\ast}$. The first exact level is at most $\min(m,k)$ and at most
$\max(\rho_{\min},\rho_{\max})+1$.
\end{theorem}

\begin{theorem}[Level one is not exact]\label{cl:gap-one}
On $W_{14}$ of \Cref{thm:lasserre-vacuous},
$\max_{R_1}x(v_1)=\frac35>\frac12=w^{\ast}(v_1)$ and $R_2(W_{14})=\{w^{\ast}\}$;
dually $\min_{R_1}x(v_1)=\frac25$ on the dual game. The certificate is
$u=(\frac35,\frac{23}{40},\frac{11}{20})
=\frac{13}{20}(\frac8{13},\frac8{13},\frac7{13})+\frac7{20}(\frac47,\frac12,\frac47)
=\frac45(\frac12,\frac12,\frac{15}{32})+\frac15(1,\frac78,\frac78)$.
\end{theorem}

\begin{theorem}[The level-one relaxation does not decide the threshold]\label{cl:dw}
For the stopping SSG $DW$ on $27$ vertices ($3$ Max, $3$ Min) joining $W_{14}$
and its dual under an average root $s$: $w^{\ast}(s)=\frac12$ and
$\min_{R_1}x(s)=\frac9{20}<\frac12<\frac{11}{20}=\max_{R_1}x(s)$, while
$R_2(DW)=\{w^{\ast}\}$.
\end{theorem}

\begin{corollary}[What an instance defeating the hierarchy must contain]\label{cl:barrier}
If $\max_{R_j}x(v)>w^{\ast}(v)$ then $G$ has more than $j$ Max vertices and more
than $j$ reversing ones; if also $\min_{R_j}x(v)<w^{\ast}(v)$ then the same holds
for $\Vmin$. No one-player game and no game with $\min(m,k)\le1$ defeats $R_1$ in
both directions.
\end{corollary}
